import { cloneElement, useMemo, useRef } from 'react';
import { PanResponder } from 'react-native';
import type { StudioGestureProps } from './studio-gesture-types';

/** Browser responder transport. Native resolves the Gesture Handler sibling. */
export function StudioGesture(props: StudioGestureProps) {
  const current = useRef(props); current.current = props;
  const responder = useMemo(() => PanResponder.create({
    onStartShouldSetPanResponder: event => !current.current.disabled && event.nativeEvent.touches.length === 1,
    onPanResponderGrant: event => current.current.onBegin({ x: event.nativeEvent.pageX, y: event.nativeEvent.pageY }),
    onPanResponderStart: event => { if (event.nativeEvent.touches.length !== 1) current.current.onCancel(); },
    onPanResponderMove: (event, state) => current.current.onMove({ x: event.nativeEvent.pageX, y: event.nativeEvent.pageY }, state.numberActiveTouches),
    onPanResponderRelease: event => current.current.onRelease({ x: event.nativeEvent.pageX, y: event.nativeEvent.pageY }),
    onPanResponderTerminationRequest: () => true,
    onPanResponderTerminate: () => current.current.onCancel(),
  }), []);
  return cloneElement(props.children, responder.panHandlers);
}

import { useMemo, useRef } from 'react';
import { Gesture, GestureDetector } from 'react-native-gesture-handler';
import type { StudioGestureProps, GesturePoint } from './studio-gesture-types';

/** Native recognition; document commands and async measurement stay on JS. */
export function StudioGesture(props: StudioGestureProps) {
  const current = useRef(props); current.current = props;
  const gesture = useMemo(() => {
    let start: GesturePoint = { x: 0, y: 0 };
    let panClaimed = false;
    let tapRejected = false;
    const pan = Gesture.Pan()
      .enabled(!props.disabled).minDistance(0).maxPointers(1).runOnJS(true)
      // Pan may remain BEGAN for DOWN→UP without a MOVE, even at distance zero.
      .onBegin(event => { start = { x: event.absoluteX, y: event.absoluteY }; panClaimed = false; })
      .onStart(() => { panClaimed = true; current.current.onBegin(start); })
      .onTouchesDown(event => { if (event.numberOfTouches !== 1) current.current.onCancel(); })
      .onUpdate(event => current.current.onMove({ x: event.absoluteX, y: event.absoluteY }, event.numberOfPointers))
      .onEnd((event, success) => {
        if (success) current.current.onRelease({ x: event.absoluteX, y: event.absoluteY });
        else if (panClaimed) current.current.onCancel();
      })
      // The losing Pan must not cancel the winning Tap's async release.
      .onFinalize((_event, success) => { if (!success && panClaimed) current.current.onCancel(); });
    const tap = Gesture.Tap().enabled(!props.disabled).maxDistance(4).runOnJS(true)
      .onBegin(event => { tapRejected = event.numberOfPointers !== 1; })
      .onTouchesDown(event => { if (event.numberOfTouches !== 1) tapRejected = true; })
      .onEnd((event, success) => {
        if (!success || tapRejected) return;
        const point = { x: event.absoluteX, y: event.absoluteY };
        current.current.onBegin(point);
        current.current.onRelease(point);
      });
    return Gesture.Race(pan, tap);
  }, [props.disabled]);
  return <GestureDetector gesture={gesture}>{props.children}</GestureDetector>;
}

import type { ReactElement } from 'react';
export type GesturePoint = { x: number; y: number };
export type StudioGestureProps = {
  children: ReactElement; disabled?: boolean;
  onBegin: (point: GesturePoint) => void;
  onMove: (point: GesturePoint, touches: number) => void;
  onRelease: (point: GesturePoint) => void;
  onCancel: () => void;
};

/** RNWeb exposes key directly; native RN keyboard events carry it in nativeEvent. */
export type StudioKeyboardEvent = {
  readonly key?: string;
  readonly nativeEvent?: { readonly key?: string };
};
export function keyboardKey(event: StudioKeyboardEvent): string | undefined {
  return event.key ?? event.nativeEvent?.key;
}

import { PanResponderDrag } from '@/components/ui/gestures/PanResponderDrag';
import type { DragTransport } from '@/components/ui/gestures/drag-transport';

/** Pointer recogniser for NYC-Tron drag parts in Forge: the browser responder
 * here, Gesture Handler on native (drag-transport.native.ts), matching
 * StudioGesture so docking and reordering keep their platform recognisers. */
export const forgeDragTransport: DragTransport = PanResponderDrag;

import { GestureHandlerDrag } from '@/components/ui/gestures/GestureHandlerDrag';
import type { DragTransport } from '@/components/ui/gestures/drag-transport';

/** Native drags run on Gesture Handler, as StudioGesture does. */
export const forgeDragTransport: DragTransport = GestureHandlerDrag;
